535	// ProcessEntry 由接班人逐项处理交接事项，须填写操作人。
536	// action 为 confirm（确认接收）、return（退回，须填原因）或 track（继续跟踪，须填跟踪说明和后续负责人）。
537	// 已退回项表示等待交班人补充，只有在原交接记录上成功重新提交、恢复待处理后才能再次
538	// 确认、继续跟踪或退回；未重新提交前直接处理一律返回状态错误，且不改变任何数据。
539	// 最后一项成功接收使整份交接首次全部明确接收时，完成时间记为本次成功处理时间；
540	// 若记录里存在补齐前误写（或零值）的旧完成时间，一并以本次时间覆盖。本次处理失败、
541	// 退回或仍有未接收项时不写完成时间，交接不能提前完成。
542	func (svc *Service) ProcessEntry(handoverID, itemID string, action EntryAction, operator, reason, trackingNote, nextFollowOwner string) (Handover, error) {
543		handoverID = clean(handoverID)
544		itemID = clean(itemID)
545		operator = clean(operator)
546		reason = clean(reason)
547		trackingNote = clean(trackingNote)
548		nextFollowOwner = clean(nextFollowOwner)
549	
550		if action != ActionConfirm && action != ActionReturn && action != ActionTrack {
551			return Handover{}, fmt.Errorf("%w：未知操作 %q", ErrInvalidInput, action)
552		}
553		if err := requireNonEmpty("操作人", operator); err != nil {
554			return Handover{}, err
555		}
556	
557		var result Handover
558		err := svc.store.mutate(func(d *Data) error {
559			h, _ := findHandover(d, handoverID)
560			if h == nil {
561				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
562			}
563			e, _ := findEntry(h, itemID)
564			if e == nil {
565				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
566			}
567			if e.Status.Received() {
568				return fmt.Errorf("%w：事项 %s 已%s，不能重复处理或退回",
569					ErrHandoverState, e.ItemID, e.Status.Label())
570			}
571			if e.Status == EntryReturned {
572				// 退回表示等待交班人补充：必须先在原交接记录上补充说明并重新提交，
573				// 该项恢复待处理后才能再次确认、继续跟踪或退回。即使本次填写了
574				// 操作人、退回原因或跟踪说明，也不能跳过这一步。
575				return fmt.Errorf("%w：事项 %s 已退回，正等待交班人补充说明并在原交接记录 %s 上重新提交；请先完成补充并重新提交后再处理",
576					ErrHandoverState, e.ItemID, h.ID)
577			}
578			switch action {
579			case ActionReturn:
580				if err := requireNonEmpty("退回原因", reason); err != nil {
581					return err
582				}
583			case ActionTrack:
584				if err := requireNonEmpty("跟踪说明", trackingNote); err != nil {
585					return err
586				}
587				if err := requireNonEmpty("后续负责人", nextFollowOwner); err != nil {
588					return err
589				}
590			}
591	
592			now := svc.now()
593			switch action {
594			case ActionConfirm:
595				e.Status = EntryConfirmed
596			case ActionTrack:
597				e.Status = EntryTracking
598				e.TrackingNote = trackingNote
599				e.FollowOwner = nextFollowOwner
600			case ActionReturn:
601				e.Status = EntryReturned
602				e.Rounds = append(e.Rounds, ReturnRound{
603					Seq:            len(e.Rounds) + 1,
604					ReturnedAt:     now,
605					ReturnOperator: operator,
606					Reason:         reason,
607				})
608			}
609			e.Operator = operator
610			e.ProcessedAt = &now
611	
612			if action != ActionReturn {
613				// 确认与继续跟踪都进入接班班次的未关闭清单，保留原编号与历史。
614				if it, _ := findItem(d, e.ItemID); it != nil && it.CurrentShiftID == h.FromShiftID {
615					it.CurrentShiftID = h.ToShiftID
616					if !contains(it.ShiftIDs, h.ToShiftID) {
617						it.ShiftIDs = append(it.ShiftIDs, h.ToShiftID)
618					}
619					detail := receivedDetailText(h, action, e.Status.Label(), trackingNote, nextFollowOwner)
620					if action == ActionTrack {
621						// 继续跟踪指定新的后续负责人，回写到事项并保留跟踪说明。
622						it.FollowOwner = nextFollowOwner
623					}
624					it.Events = append(it.Events, ItemEvent{At: now, Kind: "received", Operator: operator, Detail: detail})
625				}
626			}
627	
628			if h.Completed() {
629				// 完成时间记录这份交接真正接收齐全部事项的时刻：以最后一次成功
630				// 接收（确认或继续跟踪）的处理时间为准。旧数据可能在清单仍有结果
631				// 缺失、无法识别、待处理或退回项时就误写过完成时间（或只留下零值）：
632				// 接班人逐项补齐、整份交接首次全部明确接收时，用本次成功处理时间
633				// 覆盖那个旧时间，不能沿用补齐前的时刻；旧时间缺失（nil）时同样在
634				// 本次补上。未全部接收（如本次退回、仍有异常结果项）时不写入，
635				// 交接保持未完成。正常流程与空清单在首次全部接收时写入，之后已接收
636				// 项无法再处理，完成时间不会被改写。
637				h.CompletedAt = &now
638			}
639			result = *h
640			return nil
641		})
642		return result, err
643	}
644	
645	// validProcessedAt 报告处理时间是否真实记录：nil 或零值
646	// （0001-01-01T00:00:00Z）都视为未记录，不推测补齐。
647	func validProcessedAt(t *time.Time) bool { return t != nil && !t.IsZero() }
648	
649	func contains(xs []string, x string) bool {
650		for _, v := range xs {
651			if v == x {
652				return true
653			}
654		}
655		return false
656	}
657	
658	// ResubmitReturned 由交班人对退回项追加非空说明并在同一交接记录上重新提交；
659	// 补充写入最近一次退回记录（保留该轮原因、退回人和退回时间，并记录补充人、
660	// 补充时间与重新提交时间），以前各轮说明不覆盖。只有该项恢复待处理，当前结果的
661	// 接班处理人与处理时间显示为尚未处理；原文、严重程度、限制条件不变，事项仍留在
662	// 交班班次，同一交接的其他事项不受影响。重新提交本身不表示接收。
663	// 对待处理、已确认或继续跟踪的事项重新提交报状态错误，不写入补充说明。
664	func (svc *Service) ResubmitReturned(handoverID, itemID, operator, supplement string) (Handover, error) {
665		handoverID = clean(handoverID)
666		itemID = clean(itemID)
667		operator = clean(operator)
668		supplement = clean(supplement)
669		if err := requireNonEmpty("操作人", operator); err != nil {
670			return Handover{}, err
671		}
672		if err := requireNonEmpty("补充说明", supplement); err != nil {
673			return Handover{}, err
674		}
675	
676		var result Handover
677		err := svc.store.mutate(func(d *Data) error {
678			h, _ := findHandover(d, handoverID)
679			if h == nil {
680				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
681			}
682			e, _ := findEntry(h, itemID)
683			if e == nil {
684				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
685			}
686			if e.Status != EntryReturned {
687				return fmt.Errorf("%w：事项 %s 当前状态为 %s，只有退回项可以补充说明后重新提交",
688					ErrHandoverState, e.ItemID, e.Status.Label())
689			}
690			if len(e.Rounds) == 0 {
691				return fmt.Errorf("%w：事项 %s 缺少退回记录", ErrHandoverState, e.ItemID)
692			}
693			round := &e.Rounds[len(e.Rounds)-1]
694			if round.ResubmittedAt != nil {
695				return fmt.Errorf("%w：事项 %s 已重新提交，等待接班人处理", ErrHandoverState, e.ItemID)
696			}
697			now := svc.now()
698			round.Supplement = supplement
699			round.SupplementOperator = operator
700			round.SupplementAt = &now
701			round.ResubmittedAt = &now
702			// 仅这一个事项恢复待处理：当前结果的接班处理人与处理时间显示为
703			// 尚未处理；上一轮退回信息仍完整保留在 Rounds 历史中。
704			e.Status = EntryPending
705			e.Operator = ""
706			e.ProcessedAt = nil
707			result = *h
708			return nil
709		})
710		return result, err
711	}
