127	// TestJourneyEventsAndResultsDoNotShareStorage：同一份结果里，处理经过与交接
128	// 当前结果可能展示同一次补充；两者各是一份副本，仅调整其中一处的补充时间，
129	// 另一处保留原值。
130	func TestJourneyEventsAndResultsDoNotShareStorage(t *testing.T) {
