147			t.Fatalf("前置：当前结果的退回轮次应记录补充时间与重新提交时间")
148		}
149		origEvent, origResult := *res.SupplementAt, *round.SupplementAt
150		if !origEvent.Equal(origResult) {
151			t.Fatalf("前置：两处展示同一次补充，时间应一致：%v vs %v", origEvent, origResult)
152		}
