260		j.Item.Content = "篡改内容"
261		j.Item.Events = append(j.Item.Events, ItemEvent{At: forge, Kind: "closed", Operator: "篡改人"})
262		j.Item.ShiftIDs = append(j.Item.ShiftIDs, "S999")
263		again, err := f.svc.ItemJourney(it.ID)
264		if err != nil {
265			t.Fatalf("journey again: %v", err)
266		}
267		if again.HasHandovers || again.Item.Content != "未交接事项" ||
268			len(again.Item.Events) != 1 || len(again.Item.ShiftIDs) != 1 {
269			t.Fatalf("改动结果不应影响再次查询：%+v", again.Item)
270		}
