10	)
11	
12	// failedCloseExpectations 汇总结束失败尝试发生前已保存的业务事实，供 reopen
13	// 前后用同一组期望核对，以及成功结束后对照。
14	type failedCloseExpectations struct {
15		aID, bID, hID           string
16		idOpen, idNew, idClosed string
17		aClosedAt               time.Time // 上一班成功结束的时间（其结束时记录不受影响）
18		idClosedAt              time.Time // 上一班已关闭事项的关闭时间
19		handoverCreatedAt       time.Time
20		trackAt                 time.Time // 唯一交接事项成功接收（继续跟踪）的时间
21		openUpdatedAt           time.Time // 接班后第一次修改未关闭事项的时间
22		idNewClosedAt           time.Time // 本班新增事项的关闭时间
23		failAt                  time.Time // 失败的结束尝试时刻（不应留下任何痕迹）
24		reUpdateAt              time.Time // 保存恢复后再次修改未关闭事项的时间
25		successAt               time.Time // 真正成功结束本班的时间
26		origContent             string
27		origConstraints         string
28		trackNote               string
29		trackFollow             string // 接收当时指定的后续负责人（交接记录保存）
30		midContent              string
31		midConstraints          string
32		midFollow               string
33		midSeverity             Severity
34		finalContent            string
35		finalConstraints        string
36		finalFollow             string
37		finalSeverity           Severity
38	}
39	
40	// assertStillOpenAfterFailedClose 用当前打开的数据核对：保存失败后本班仍在
41	// 进行中，没有结束时间，也没有结束时事项记录；失败前已保存的事项、交接与
42	// 上一班结束时记录全部原样保留，本次失败不成为任何业务事实。
43	func assertStillOpenAfterFailedClose(t *testing.T, f *fixture, w failedCloseExpectations) {
44		t.Helper()
45	
46		// 失败尝试不新增班次或交接，也不复制事项。
47		if hs := f.svc.ListShifts(); len(hs) != 2 {
48			t.Fatalf("失败尝试不应新增班次，got %d 个：%+v", len(hs), hs)
49		}
50		if hs := f.svc.ListHandovers(); len(hs) != 1 || hs[0].ID != w.hID {
51			t.Fatalf("失败尝试不应新增交接：%+v", hs)
52		}
53		for _, id := range []string{w.idOpen, w.idNew, w.idClosed} {
54			if n := countItems(f, id); n != 1 {
55				t.Fatalf("失败尝试不应复制事项，编号 %s 出现 %d 次", id, n)
56			}
57		}
58	
59		// 本班仍在进行中：没有结束时间，也没有结束时记录。
60		b, err := f.svc.GetShift(w.bID)
61		if err != nil {
62			t.Fatalf("get shift: %v", err)
63		}
64		if b.Closed || b.ClosedAt != nil || b.CloseRecord != nil {
65			t.Fatalf("保存失败后班次应仍在进行中、无结束时间与结束时记录：%+v", b)
66		}
67	
68		// 查看本班：事项区仍展示当前信息，不被标成结束时记录或历史不完整；
69		// 本班只含两项（本班新增已关闭项、上一班交来仍未关闭项），各一次并按
70		// 编号排列；上一班已关闭的事项不属于本班，不能被拉进本班清单。
71		repB, err := f.svc.ShiftReport(w.bID)
72		if err != nil {
73			t.Fatalf("report b: %v", err)
74		}
75		if repB.Shift.Closed || repB.ItemsAtClose || repB.HistoryIncomplete {
76			t.Fatalf("进行中班次不应出现结束时记录或历史不完整标记：%+v", repB.Shift)
77		}
78		if len(repB.CloseItems) != 0 {
79			t.Fatalf("失败尝试不应生成结束时事项记录：%+v", repB.CloseItems)
80		}
81		if len(repB.Items) != 2 {
82			t.Fatalf("本班当前事项应为2项，got %d：%+v", len(repB.Items), repB.Items)
83		}
84		if repB.Items[0].ID != w.idOpen || repB.Items[1].ID != w.idNew {
85			t.Fatalf("事项应按编号排列且各出现一次：%s %s", repB.Items[0].ID, repB.Items[1].ID)
86		}
87		cur := map[string]Item{}
88		for _, it := range repB.Items {
89			cur[it.ID] = it
90		}
91		// 接收到的未关闭事项：保留接班后修改过的内容、严重程度、限制条件与负责人，
92		// 仍在本班、仍未关闭，不能退回上一班，也不能多记一条关闭。
93		op := cur[w.idOpen]
94		if op.Content != w.midContent || op.Severity != w.midSeverity ||
95			op.Constraints != w.midConstraints || op.FollowOwner != w.midFollow {
96			t.Fatalf("未关闭事项应保持接班后修改的当前信息：%+v", op)
97		}
98		if op.Closed || op.ClosedAt != nil || op.CloseOperator != "" {
99			t.Fatalf("未关闭事项不能因失败尝试变成已关闭：%+v", op)
100		}
101		if op.OriginShiftID != w.aID || op.CurrentShiftID != w.bID ||
102			len(op.ShiftIDs) != 2 || op.ShiftIDs[0] != w.aID || op.ShiftIDs[1] != w.bID {
103			t.Fatalf("接收到的事项不能退回上一班，编号与流经班次应保持：%+v", op)
104		}
105		// 本班新增且已关闭的事项：关闭人与关闭时间保持原样，不能被重新打开。
106		nw := cur[w.idNew]
107		if !nw.Closed || nw.CloseOperator != "李四" ||
108			nw.ClosedAt == nil || !nw.ClosedAt.Equal(w.idNewClosedAt) {
109			t.Fatalf("本班已关闭事项的关闭人与关闭时间应保持原样：%+v", nw)
110		}
111		if nw.OriginShiftID != w.bID || nw.CurrentShiftID != w.bID ||
112			len(nw.ShiftIDs) != 1 || nw.ShiftIDs[0] != w.bID {
113			t.Fatalf("本班新增事项所在班次应保持：%+v", nw)
114		}
115		// 上一班已关闭事项仍在上一班、保持关闭。
116		old, err := f.svc.GetItem(w.idClosed)
117		if err != nil {
118			t.Fatalf("get closed item: %v", err)
119		}
120		if !old.Closed || old.CloseOperator != "张三" ||
121			old.ClosedAt == nil || !old.ClosedAt.Equal(w.idClosedAt) {
122			t.Fatalf("上一班已关闭事项不能被重新打开：%+v", old)
123		}
124		if old.OriginShiftID != w.aID || old.CurrentShiftID != w.aID ||
125			len(old.ShiftIDs) != 1 || old.ShiftIDs[0] != w.aID {
126			t.Fatalf("上一班已关闭事项所在班次应保持：%+v", old)
127		}
128	
129		// 交接：接收结果、处理人、处理时间与完成时间保留；交接记录里继续跟踪
130		// 当时的跟踪说明与后续负责人是接收时刻保存的值，不被接班后的修改改写。
131		h, err := f.svc.GetHandover(w.hID)
132		if err != nil {
133			t.Fatalf("get handover: %v", err)
134		}
135		if !h.Completed() || h.CompletedAt == nil || !h.CompletedAt.Equal(w.trackAt) {
136			t.Fatalf("既有交接的接收结果与完成时间应保留：%+v", h)
137		}
138		if !h.CreatedAt.Equal(w.handoverCreatedAt) || h.FromShiftID != w.aID || h.ToShiftID != w.bID {
139			t.Fatalf("交接编号、两班关系与发起时间应保留：%+v", h)
140		}
141		if len(h.Entries) != 1 {
142			t.Fatalf("交接清单不应变化，got %d 项", len(h.Entries))
143		}
144		e := findEntryOf(t, h, w.idOpen)
145		if e.Status != EntryTracking || e.Operator != "李四" ||
146			e.ProcessedAt == nil || !e.ProcessedAt.Equal(w.trackAt) ||
147			e.TrackingNote != w.trackNote || e.FollowOwner != w.trackFollow {
148			t.Fatalf("接收方式、处理人、处理时间、跟踪说明与当时负责人应保留：%+v", e)
149		}
150		if len(e.Rounds) != 0 {
151			t.Fatalf("失败尝试不应产生退回/补充经过：%+v", e.Rounds)
152		}
153	
154		// 上一班保持成功结束，其结束时记录仍是上一班自己结束时的内容：
155		// 未关闭事项保留原内容、原负责人且当时未关闭；已关闭事项保留关闭人与时间。
156		sa, err := f.svc.GetShift(w.aID)
157		if err != nil {
158			t.Fatalf("get shift a: %v", err)
159		}
160		if !sa.Closed || sa.ClosedAt == nil || !sa.ClosedAt.Equal(w.aClosedAt) || sa.CloseRecord == nil {
161			t.Fatalf("上一班的结束状态、结束时间与结束时记录应保留：%+v", sa)
162		}
163		repA, err := f.svc.ShiftReport(w.aID)
164		if err != nil {
165			t.Fatalf("report a: %v", err)
166		}
167		if !repA.ItemsAtClose || len(repA.CloseItems) != 2 {
168			t.Fatalf("上一班结束时记录应保留2项，got %+v", repA.CloseItems)
169		}
170		snapOpen := findCloseItem(repA, w.idOpen)
171		if snapOpen == nil || snapOpen.Content != w.origContent ||
172			snapOpen.Severity != SeverityNormal || snapOpen.Constraints != w.origConstraints ||
173			snapOpen.FollowOwner != "李四" || snapOpen.Closed {
174			t.Fatalf("上一班记录中的未关闭事项应保持结束时原样：%+v", snapOpen)
175		}
176		snapClosed := findCloseItem(repA, w.idClosed)
177		if snapClosed == nil || !snapClosed.Closed || snapClosed.CloseOperator != "张三" ||
178			snapClosed.ClosedAt == nil || !snapClosed.ClosedAt.Equal(w.idClosedAt) {
179			t.Fatalf("上一班记录中的已关闭事项应保持关闭人与关闭时间：%+v", snapClosed)
180		}
181	
182		// 展示层与保存事实一致：本班事项区是当前信息而非结束时记录，不出现失败
183		// 尝试的结束时间；上一班仍展示自己的结束时记录。
184		textB := FormatReport(repB)
185		if strings.Contains(textB, "结束时记录") || strings.Contains(textB, fmtTime(w.failAt)) {
186			t.Fatalf("本班报告不应出现结束时记录或失败尝试时刻：\n%s", textB)
187		}
188		if !strings.Contains(textB, "\n事项：\n") || !strings.Contains(textB, w.midContent) ||
189			!strings.Contains(textB, "后续负责人："+w.midFollow) {
190			t.Fatalf("本班报告应展示未关闭事项的当前信息：\n%s", textB)
191		}
192		if !strings.Contains(textB, fmt.Sprintf("已关闭（李四 于 %s）", fmtTime(w.idNewClosedAt))) {
193			t.Fatalf("本班报告应保留已关闭事项的关闭人与关闭时间：\n%s", textB)
194		}
195		if !strings.Contains(FormatShift(b), "[进行中]") {
196			t.Fatalf("班次摘要应显示进行中：%s", FormatShift(b))
197		}
198		if !strings.Contains(textB, "已完成 "+fmtTime(w.trackAt)) ||
199			!strings.Contains(textB, w.trackFollow) {
200			t.Fatalf("本班报告中的接班交接应保留完成时间与接收当时的负责人：\n%s", textB)
201		}
202		textA := FormatReport(repA)
203		if !strings.Contains(textA, "结束时记录") || !strings.Contains(textA, w.origContent) ||
204			!strings.Contains(textA, "结束时后续负责人：李四") {
205			t.Fatalf("上一班报告应仍展示自己的原始结束时记录：\n%s", textA)
206		}
207	
208		// 事项处理经过只含失败前已保存的事实，不混入失败尝试时刻；接收到的事项
209		// 保留接收经过，两个已关闭事项没有新的关闭/重开经过。
210		jOpen, err := f.svc.ItemJourney(w.idOpen)
211		if err != nil {
212			t.Fatalf("journey open: %v", err)
213		}
214		if got := joinStrings(journeyKinds(jOpen)); got != "created,handover-init,track,updated" {
215			t.Fatalf("未关闭事项处理经过应只含失败前事实，got %s", got)
216		}
217		updates := 0
218		for _, ev := range jOpen.Events {
219			if ev.TimeKnown && ev.At.Equal(w.failAt) {
220				t.Fatalf("失败尝试时刻 %s 不应出现在处理经过：%+v", w.failAt, ev)
221			}
222			if ev.Kind == "updated" {
223				updates++
224				if !ev.TimeKnown || !ev.At.Equal(w.openUpdatedAt) {
225					t.Fatalf("唯一的修改记录应为失败前已保存的那次：%+v", ev)
226				}
227			}
228		}
229		if updates != 1 {
230			t.Fatalf("失败前应只有一次成功修改记录，got %d", updates)
231		}
232		if len(jOpen.Results) != 1 || jOpen.Results[0].Entry.Status != EntryTracking ||
233			jOpen.Results[0].Entry.FollowOwner != w.trackFollow {
234			t.Fatalf("交接当前结果应保留接收时的继续跟踪记录：%+v", jOpen.Results)
235		}
236		for _, id := range []string{w.idNew, w.idClosed} {
237			j, err := f.svc.ItemJourney(id)
238			if err != nil {
239				t.Fatalf("journey %s: %v", id, err)
240			}
241			if got := joinStrings(journeyKinds(j)); got != "created,closed" {
242				t.Fatalf("已关闭事项 %s 的处理经过应保持创建与关闭，got %s", id, got)
243			}
244			for _, ev := range j.Events {
245				if ev.TimeKnown && ev.At.Equal(w.failAt) {
246					t.Fatalf("失败尝试时刻不应出现在事项 %s 的处理经过：%+v", id, ev)
247				}
248			}
249		}
250	}
251	
252	// assertClosedWithSuccessRecord 用当前打开的数据核对：保存恢复后本班成功
253	// 结束，结束时间与结束时记录都只属于这次成功操作；失败尝试无痕迹。
254	func assertClosedWithSuccessRecord(t *testing.T, f *fixture, w failedCloseExpectations) {
255		t.Helper()
256	
257		b, err := f.svc.GetShift(w.bID)
258		if err != nil {
259			t.Fatalf("get shift after success: %v", err)
260		}
261		if !b.Closed || b.ClosedAt == nil || !b.ClosedAt.Equal(w.successAt) || b.CloseRecord == nil {
262			t.Fatalf("本班应以成功操作时刻结束并留下结束时记录：%+v", b)
263		}
264	
265		repB, err := f.svc.ShiftReport(w.bID)
266		if err != nil {
267			t.Fatalf("report b after success: %v", err)
268		}
269		if !repB.ItemsAtClose || repB.HistoryIncomplete {
270			t.Fatalf("成功结束后事项区应标为结束时记录：%+v", repB)
271		}
272		// 结束时记录含本班新增且已关闭的事项与已经接收但未关闭的事项，每项一次。
273		if len(repB.CloseItems) != 2 {
274			t.Fatalf("结束时记录应含2项，got %d", len(repB.CloseItems))
275		}
276		if repB.CloseItems[0].ItemID != w.idOpen || repB.CloseItems[1].ItemID != w.idNew {
277			t.Fatalf("结束时记录应按编号排列、每项一次：%s %s",
278				repB.CloseItems[0].ItemID, repB.CloseItems[1].ItemID)
279		}
280		// 未关闭事项按成功时的信息冻结，保留再次修改后的内容、严重程度、限制条件
281		// 与负责人，结束时仍未关闭。
282		so := findCloseItem(repB, w.idOpen)
283		if so == nil || so.Content != w.finalContent || so.Severity != w.finalSeverity ||
284			so.Constraints != w.finalConstraints || so.FollowOwner != w.finalFollow || so.Closed ||
285			so.CloseOperator != "" || so.ClosedAt != nil {
286			t.Fatalf("未关闭事项应以成功时的信息冻结且仍为未关闭：%+v", so)
287		}
288		// 已关闭事项保留原关闭人与关闭时间，不被重新打开。
289		sn := findCloseItem(repB, w.idNew)
290		if sn == nil || !sn.Closed || sn.CloseOperator != "李四" ||
291			sn.ClosedAt == nil || !sn.ClosedAt.Equal(w.idNewClosedAt) {
292			t.Fatalf("已关闭事项应保留原关闭人与关闭时间：%+v", sn)
293		}
294		// 上一班已关闭事项不属于本班结束时记录。
295		if findCloseItem(repB, w.idClosed) != nil {
296			t.Fatalf("上一班已关闭事项不应出现在本班结束时记录中")
297		}
298		latest := repB.LatestItems[w.idOpen]
299		if latest.CurrentShiftID != w.bID || latest.FollowOwner != w.finalFollow || latest.Closed {
300			t.Fatalf("最新状态对照应反映成功时的未关闭事项：%+v", latest)
301		}
302	
303		textB := FormatReport(repB)
304		if !strings.Contains(textB, "以下为结束时记录") ||
305			!strings.Contains(textB, w.finalContent) ||
306			!strings.Contains(textB, "结束时后续负责人："+w.finalFollow) {
307			t.Fatalf("本班报告应按成功时信息展示结束时记录：\n%s", textB)
308		}
309		if !strings.Contains(textB, fmt.Sprintf("结束时已关闭（李四 于 %s）", fmtTime(w.idNewClosedAt))) {
310			t.Fatalf("本班结束时记录应保留已关闭项的关闭人与关闭时间：\n%s", textB)
311		}
312		if strings.Contains(textB, fmtTime(w.failAt)) || strings.Contains(textB, w.midContent) {
313			t.Fatalf("失败尝试时刻与失败前的中间值不应进入成功后的结束时记录：\n%s", textB)
314		}
315	
316		// 上一班仍展示它自己的原始结束时记录，不随后班修改或成功结束改变。
317		repA, err := f.svc.ShiftReport(w.aID)
318		if err != nil {
319			t.Fatalf("report a after success: %v", err)
320		}
321		sa := findCloseItem(repA, w.idOpen)
322		if sa == nil || sa.Content != w.origContent || sa.FollowOwner != "李四" || sa.Closed {
323			t.Fatalf("上一班应仍展示自己的原始记录：%+v", sa)
324		}
325		sc := findCloseItem(repA, w.idClosed)
326		if sc == nil || !sc.Closed || sc.CloseOperator != "张三" {
327			t.Fatalf("上一班已关闭事项记录应保留：%+v", sc)
328		}
329		textA := FormatReport(repA)
330		if !strings.Contains(textA, "以下为结束时记录") || !strings.Contains(textA, w.origContent) {
331			t.Fatalf("上一班报告应仍展示自己的原始结束时记录：\n%s", textA)
332		}
333	
334		// 既有交接仍是原来的接收结果；交接记录中继续跟踪当时的负责人不被后来的
335		// 修改覆盖。
336		h, err := f.svc.GetHandover(w.hID)
337		if err != nil {
338			t.Fatalf("get handover after success: %v", err)
339		}
340		if !h.Completed() || h.CompletedAt == nil || !h.CompletedAt.Equal(w.trackAt) {
341			t.Fatalf("交接完成时间应仍是最后一项接收的时刻：%+v", h)
342		}
343		e := findEntryOf(t, h, w.idOpen)
344		if e.Status != EntryTracking || e.Operator != "李四" ||
345			e.ProcessedAt == nil || !e.ProcessedAt.Equal(w.trackAt) ||
346			e.TrackingNote != w.trackNote || e.FollowOwner != w.trackFollow {
347			t.Fatalf("交接接收记录应保留接收当时保存的信息：%+v", e)
348		}
349	
350		// 未关闭事项本身：仍未关闭、保留编号与流经班次，处理经过只留下成功的
351		// 业务事实（一次接收、两次修改），没有失败尝试时刻。
352		it, err := f.svc.GetItem(w.idOpen)
353		if err != nil {
354			t.Fatalf("get item after success: %v", err)
355		}
356		if it.Closed || it.Content != w.finalContent || it.Severity != w.finalSeverity ||
357			it.Constraints != w.finalConstraints || it.FollowOwner != w.finalFollow {
358			t.Fatalf("未关闭事项应保持成功时的当前信息：%+v", it)
359		}
360		if it.OriginShiftID != w.aID || it.CurrentShiftID != w.bID ||
361			len(it.ShiftIDs) != 2 || it.ShiftIDs[0] != w.aID || it.ShiftIDs[1] != w.bID {
362			t.Fatalf("事项编号与流经班次应保持：%+v", it)
363		}
364		// 事项自身历史：只发生过一次接收、两次成功修改；没有失败尝试的任何痕迹。
365		kinds := make([]string, 0, len(it.Events))
366		received := 0
367		for _, ev := range it.Events {
368			kinds = append(kinds, ev.Kind)
369			if ev.Kind == "received" {
370				received++
371			}
372			if !ev.At.IsZero() && ev.At.Equal(w.failAt) {
373				t.Fatalf("失败尝试时刻不应出现在事项历史：%+v", ev)
374			}
375		}
376		if received != 1 || joinStrings(kinds) != "created,received,updated,updated" {
377			t.Fatalf("事项历史应只留下一次接收与两次成功修改，got %v", kinds)
378		}
379		j, err := f.svc.ItemJourney(w.idOpen)
380		if err != nil {
381			t.Fatalf("journey after success: %v", err)
382		}
383		if got := joinStrings(journeyKinds(j)); got != "created,handover-init,track,updated,updated" {
384			t.Fatalf("处理经过应呈现一次接收与两次成功修改，got %s", got)
385		}
386		updatedAt := []time.Time{}
387		for _, ev := range j.Events {
388			if ev.TimeKnown && ev.At.Equal(w.failAt) {
389				t.Fatalf("失败尝试时刻不应出现在成功后的处理经过：%+v", ev)
390			}
391			if ev.Kind == "updated" {
392				updatedAt = append(updatedAt, ev.At)
393			}
394		}
395		if len(updatedAt) != 2 ||
396			!updatedAt[0].Equal(w.openUpdatedAt) || !updatedAt[1].Equal(w.reUpdateAt) {
397			t.Fatalf("两次修改应分别为接班后与保存恢复后的成功修改：%v", updatedAt)
398		}
399	
400		// 已结束班次不能重复结束。
401		if _, err := f.svc.CloseShift(w.bID); !errors.Is(err, ErrShiftClosed) {
402			t.Fatalf("成功结束后重复结束应报错，got %v", err)
403		}
404	}
405	
406	// TestCloseShiftSaveFailureAtomicRollback：编号正确、班次仍在进行中、接班
407	// 交接已全部明确接收、本班又存在已关闭与未关闭事项时结束班次，业务条件全部
408	// 成立、真正进入保存过程后本地写盘失败——结束操作必须明确返回保存错误，
409	// 不能当成结束成功；内存与磁盘都回到失败前：班次仍进行中、无结束时间、无
410	// 本次生成的结束时事项记录，事项区仍展示当前信息；未关闭事项保持接班后
411	// 修改的内容/严重程度/限制条件/负责人且不退回上一班，已关闭事项不被重新
412	// 打开；既有交接的接收结果、处理人、处理时间与完成时间保留，上一班的
413	// 结束时记录不受影响，原数据文件内容一个字节不变。保存恢复后仍能在同一
414	// 会话中修改本班未关闭事项并正常结束：结束时间属于这次成功操作，结束时
415	// 记录按成功时信息保存（含本班新增已关闭项与已接收未关闭项，每项一次；
416	// 已关闭项保留原关闭人与关闭时间），班次报告此时才标为结束时记录，上一班
417	// 仍展示自己的原始记录。
418	func TestCloseShiftSaveFailureAtomicRollback(t *testing.T) {
419		f := newFixture(t)
420		a := mustShift(t, f, "调度", "张三", tsDay(2, 8, 0), tsDay(2, 16, 0), "")
421		b := mustShift(t, f, "调度", "李四", tsDay(2, 16, 0), tsDay(2, 23, 0), "")
422	
423		// 上一班：一项未关闭（随后交给本班），一项结束前已关闭。
424		idOpen, err := f.svc.AddItem(a.ID, "上一班遗留的压力异常", SeverityNormal, "", "李四")
425		if err != nil {
426			t.Fatalf("add open item: %v", err)
427		}
428		idClosed, err := f.svc.AddItem(a.ID, "上一班已关闭的巡检事项", SeverityImportant, "需复查记录", "李四")
429		if err != nil {
430			t.Fatalf("add closed item: %v", err)
431		}
432		itemClosedAt := tsDay(2, 14, 0)
433		f.svc.nowAt(func() time.Time { return itemClosedAt })
434		if _, err := f.svc.CloseItem(idClosed.ID, "张三"); err != nil {
435			t.Fatalf("close item in prior shift: %v", err)
436		}
437		aClosedAt := tsDay(2, 15, 0)
438		f.svc.nowAt(func() time.Time { return aClosedAt })
439		if _, err := f.svc.CloseShift(a.ID); err != nil {
440			t.Fatalf("close prior shift: %v", err)
441		}
442	
443		// 交接完成：唯一事项由接班人继续跟踪，明确接收并指定跟踪说明与新负责人。
444		handoverCreatedAt := tsDay(2, 16, 30)
445		f.svc.nowAt(func() time.Time { return handoverCreatedAt })
446		h, err := f.svc.CreateHandover(a.ID, b.ID)
447		if err != nil {
448			t.Fatalf("create handover: %v", err)
449		}
450		trackAt := tsDay(2, 17, 30)
451		f.svc.nowAt(func() time.Time { return trackAt })
452		if _, err := f.svc.ProcessEntry(h.ID, idOpen.ID, ActionTrack, "李四", "",
453			"持续跟踪压力变化", "王五"); err != nil {
454			t.Fatalf("track: %v", err)
455		}
456	
457		// 接班后修改过未关闭事项的内容、严重程度、限制条件和后续负责人，因此
458		// 两班保存的信息有所不同。
459		openUpdatedAt := tsDay(2, 18, 0)
460		f.svc.nowAt(func() time.Time { return openUpdatedAt })
461		if _, err := f.svc.UpdateItem(idOpen.ID, "接班后修订的压力异常", SeverityUrgent,
462			"接班后新增限制", "赵六"); err != nil {
463			t.Fatalf("update received item: %v", err)
464		}
465	
466		// 本班新增一项，并在结束尝试前关闭，关闭人与关闭时间已保存。
467		f.svc.nowAt(func() time.Time { return tsDay(2, 18, 30) })
468		idNew, err := f.svc.AddItem(b.ID, "本班新增的记录归档", SeverityNormal, "", "李四")
469		if err != nil {
470			t.Fatalf("add item in current shift: %v", err)
471		}
472		idNewClosedAt := tsDay(2, 19, 0)
473		f.svc.nowAt(func() time.Time { return idNewClosedAt })
474		if _, err := f.svc.CloseItem(idNew.ID, "李四"); err != nil {
475			t.Fatalf("close new item: %v", err)
476		}
477	
478		// 前置：交接已全部明确接收，编号正确、班次进行中——结束的业务条件成立。
479		got, _ := f.svc.GetHandover(h.ID)
480		if !got.Completed() {
481			t.Fatalf("前置：交接应已全部明确接收")
482		}
483		if pre, _ := f.svc.GetShift(b.ID); pre.Closed {
484			t.Fatalf("前置：本班应仍在进行中")
485		}
486	
487		want := failedCloseExpectations{
488			aID: a.ID, bID: b.ID, hID: h.ID,
489			idOpen: idOpen.ID, idNew: idNew.ID, idClosed: idClosed.ID,
490			aClosedAt:         aClosedAt,
491			idClosedAt:        itemClosedAt,
492			handoverCreatedAt: handoverCreatedAt,
493			trackAt:           trackAt,
494			openUpdatedAt:     openUpdatedAt,
495			idNewClosedAt:     idNewClosedAt,
496			failAt:            tsDay(2, 20, 0),
497			reUpdateAt:        tsDay(2, 21, 0),
498			successAt:         tsDay(2, 22, 0),
499			origContent:       "上一班遗留的压力异常",
500			origConstraints:   "",
501			trackNote:         "持续跟踪压力变化",
502			trackFollow:       "王五",
503			midContent:        "接班后修订的压力异常",
504			midConstraints:    "接班后新增限制",
505			midFollow:         "赵六",
506			midSeverity:       SeverityUrgent,
507			finalContent:      "再次修订的压力异常",
508			finalConstraints:  "最终限制条件",
509			finalFollow:       "钱七",
510			finalSeverity:     SeverityImportant,
511		}
512	
513		// 记录失败前已落盘的文件内容，并固定失败尝试的结束时刻。
514		rawBefore, err := os.ReadFile(f.store.Path())
515		if err != nil {
516			t.Fatalf("read data file: %v", err)
517		}
518		f.svc.nowAt(func() time.Time { return want.failAt })
519	
520		// 使下一次写盘在原子保存阶段失败。
521		breakSaving(t, f)
522		_, err = f.svc.CloseShift(b.ID)
523		if err == nil {
524			t.Fatalf("保存失败时结束班次应明确返回错误，不能当成结束成功")
525		}
526		if !strings.Contains(err.Error(), "写入数据文件失败") {
527			t.Fatalf("应明确返回保存阶段的错误，got %v", err)
528		}
529		// 业务条件全部成立，不能用编号不存在、班次已结束或接班交接未完成的拒绝
530		// 来冒充这个保存失败场景。
531		if errors.Is(err, ErrInvalidInput) || errors.Is(err, ErrHandoverState) ||
532			errors.Is(err, ErrNotFound) || errors.Is(err, ErrShiftClosed) {
533			t.Fatalf("编号正确、进行中且交接已接收时的保存失败不应被报告为业务校验错误，got %v", err)
534		}
535	
536		// 当前打开的数据上查看班次、事项、交接与报告，应看到失败前的事实，而不是
537		// 只保证文件没变、查询却显示已经结束。
538		assertStillOpenAfterFailedClose(t, f, want)
539	
540		// 失败前已保存的数据文件一个字节都不应改变（原子改名未发生）。
541		rawAfter, err := os.ReadFile(f.store.Path())
542		if err != nil {
543			t.Fatalf("read data file after failure: %v", err)
544		}
545		if string(rawAfter) != string(rawBefore) {
546			t.Fatalf("保存失败不得改动既有数据文件，失败的结束尝试不能成为其中的业务事实")
547		}
548	
549		// 退出后重新打开：班次进行中、事项与交接事实与失败前一致，仍无结束时记录。
550		f.reopen(t)
551		assertStillOpenAfterFailedClose(t, f, want)
552	
553		// 保存条件恢复后，用户仍能在同一应用中修改本班未关闭事项，再正常结束本班。
554		restoreSaving(t, f)
555		f.svc.nowAt(func() time.Time { return want.reUpdateAt })
556		if _, err := f.svc.UpdateItem(idOpen.ID, want.finalContent, want.finalSeverity,
557			want.finalConstraints, want.finalFollow); err != nil {
558			t.Fatalf("恢复后应仍能修改本班未关闭事项：%v", err)
559		}
560		retry, _ := f.svc.GetItem(idOpen.ID)
561		if retry.Content != want.finalContent || retry.Severity != want.finalSeverity ||
562			retry.Constraints != want.finalConstraints || retry.FollowOwner != want.finalFollow ||
563			retry.Closed || retry.CurrentShiftID != b.ID {
564			t.Fatalf("恢复后修改应已生效且事项仍未关闭、仍在本班：%+v", retry)
565		}
566		f.svc.nowAt(func() time.Time { return want.successAt })
567		if _, err := f.svc.CloseShift(b.ID); err != nil {
568			t.Fatalf("保存恢复后结束班次应成功：%v", err)
569		}
570	
571		// 成功后的结束时间属于这次成功操作，结束时记录按成功时的事项信息保存。
572		assertClosedWithSuccessRecord(t, f, want)
573	
574		// 成功落盘的文件只包含成功事实，不包含失败尝试时刻。
575		rawSuccess, err := os.ReadFile(f.store.Path())
576		if err != nil {
577			t.Fatalf("read data file after success: %v", err)
578		}
579		if !strings.Contains(string(rawSuccess), want.successAt.Format("2006-01-02T15:04:05-07:00")) {
580			t.Fatalf("成功结束时间应已写入数据文件")
581		}
582		if strings.Contains(string(rawSuccess), want.failAt.Format("2006-01-02T15:04:05-07:00")) {
583			t.Fatalf("失败的结束尝试时刻不应留在数据文件中")
584		}
585	
586		// 退出重开后，成功结束的事实与上一班原始记录都完整保留，失败尝试仍无痕迹。
587		f.reopen(t)
588		assertClosedWithSuccessRecord(t, f, want)
589	}
590

